-- 81_BERIKARE_SLOTT_2026_07_14.sql
-- Samlar den dagliga berikarens 7 databatchar (scraper-visit-sidor PR #1–#5, #7, #8)
-- så att de körs automatiskt av apply-db-workflowen — inget manuellt Supabase-steg.
-- 45 platser: SE-slott 6 · NO 2 · DK 5 · FI 4 · SE-herrgårdar 4 · UK-slott 12 · internationella 12.
-- Alla idempotenta (ON CONFLICT (id) DO UPDATE), dedupade mot live-DB av respektive batch.
ALTER TABLE places ADD COLUMN IF NOT EXISTS source TEXT;
ALTER TABLE places ADD COLUMN IF NOT EXISTS translations JSONB;

-- hauntedplaces-slott-se-2026-07-14.sql  (svenska spökslott & herrgårdar, batch 1)
-- 6 nya platser till Hauntedplaces + Spökkartan (delat Supabase-projekt zffhdjogphqhcttkezsb).
-- Källa: svenska slott/herrgårdar via Wikidata + Wikipedia, spöksägner verifierade mot minst en
-- trovärdig källa (Wikipedia, slottens egna sidor, Myling Paranormal, Region Uppsala, lokalpress).
-- Deduplicerat mot 1305 live-platser (namn + koordinat <300 m) och mot data/hauntedplaces-*.sql.
-- Egen sv+en-text grundad i allmänt känd historia + folktro; källornas text återges ALDRIG ordagrant.
-- Idempotent: ON CONFLICT (id) DO UPDATE. Kör i Supabase SQL-editor (projekt zffhdjogphqhcttkezsb).

BEGIN;
INSERT INTO places (id, name, slug, lat, lng, country, region, type, scary, free, bookable, teaser, description, status, source, translations) VALUES
('angso-slott-vastmanland', 'Ängsö slott', 'angso-slott-vastmanland', 59.5325, 16.8575, 'Sverige', 'Västmanland', 'Slott', 4, false, true, 'På en ö i Mälaren sägs Karl XII:s hovnarr fortfarande vandra – nära 300 år efter sin död.', 'Ängsö slott reser sig på en holme i Mälaren och bär på flera spöksägner. Mest omtalad är Karl XII:s puckelryggige hovnarr Anders Luxemburg, som enligt traditionen ännu rör sig genom slottets salar långt efter sin död. Till stämningen hör också berättelser om skepnader och oförklarliga ljud i de gamla rummen. Slottet är byggnadsminne och öppnar för besök sommartid.', 'published', 'wikipedia', '{"en":{"name":"Ängsö Castle","teaser":"On an island in Lake Mälaren, Karl XII''s court jester is still said to walk — nearly 300 years after his death.","description":"Ängsö Castle stands on an islet in Lake Mälaren and carries several ghost legends. The best known concerns Anders Luxemburg, the hunchbacked court jester of King Karl XII, said by tradition to still move through the halls long after his death. Reports of shadowy figures and unexplained sounds add to the mood of the old rooms. The castle is a listed monument, open to visitors in summer."}}'::jsonb),
('svaneholms-slott-skane', 'Svaneholms slott', 'svaneholms-slott-skane', 55.50083, 13.47806, 'Sverige', 'Skåne, Skurup', 'Slott', 4, false, true, 'Renässansslottet i Skåne har en egen spökutställning – här sägs bland andra en dansande dansk kung och en vit fru gå igen.', 'Svaneholms slott i skånska Skurup är ett vattenomflutet renässansslott med så många spöksägner att det inrett en egen utställning om dem. Bland gestalterna som sägs hemsöka salarna finns den danske kungen Fredrik II som dansar i musiksalen, en vit fru och en grå munk. Många besökare har berättat om upplevelser de tolkat som övernaturliga. Slottet rymmer museum och restaurang och är öppet för besök.', 'published', 'wikipedia', '{"en":{"name":"Svaneholm Castle","teaser":"This Renaissance castle in Skåne even has its own ghost exhibition — a dancing Danish king and a White Lady are among those said to walk here.","description":"Svaneholm Castle in Skurup, Skåne, is a moated Renaissance castle with so many ghost legends that it has built an exhibition about them. Among the figures said to haunt its halls are the Danish king Frederick II dancing in the music room, a White Lady and a Grey Monk. Many visitors have described experiences they read as supernatural. The castle holds a museum and restaurant and is open to visitors."}}'::jsonb),
('skogaholms-herrgard-skansen', 'Skogaholms herrgård', 'skogaholms-herrgard-skansen', 59.32575, 18.10476, 'Sverige', 'Stockholm, Skansen', 'Herrgård', 3, false, true, 'Herrgården på Skansen bär på en mörk sägen om en budbärare som mördades för en väska full med pengar.', 'Skogaholms herrgård är en karolinsk herrgård som flyttades till friluftsmuseet Skansen i Stockholm. Till gården hör en gammal sägen om ett mord: en budbärare ska ha bragts om livet för en läderväska fylld med pengar, och en tjänare misstänktes för dådet. Berättelsen har följt med huset och ger den vackra 1700-talsmiljön en olustig underton. Herrgården visas som en del av Skansen.', 'published', 'wikipedia', '{"en":{"name":"Skogaholm Manor","teaser":"This manor at the Skansen open-air museum carries a dark legend of a messenger murdered for a bag full of money.","description":"Skogaholm Manor is a Carolean manor house relocated to the Skansen open-air museum in Stockholm. An old legend clings to it: a messenger is said to have been killed for a leather bag full of money, and a servant fell under suspicion. The tale has followed the house and lends its handsome 18th-century setting an uneasy undertone. The manor is shown as part of Skansen."}}'::jsonb),
('rosersbergs-slott-uppland', 'Rosersbergs slott', 'rosersbergs-slott-uppland', 59.57417, 17.84444, 'Sverige', 'Uppland, Sigtuna', 'Slott', 4, false, true, 'På det kungliga slottet dog en drottning 1818 – och en vaktpost sägs ha mött henne igen samma natt, med ett glas i handen.', 'Rosersbergs slott norr om Stockholm är ett av de kungliga slotten, och här avled drottning Hedvig Elisabet Charlotta år 1818. En nedärvd släktsägen berättar om en vaktpost vid hennes kista som hörde steg över det tomma golvet och plötsligt stod ansikte mot ansikte med den döda drottningen, som med hes röst räckte honom ett glas med en gulaktig dryck. Slottet är statligt byggnadsminne med bevarade sengustavianska interiörer och visningar sommartid.', 'published', 'myling', '{"en":{"name":"Rosersberg Palace","teaser":"A queen died at this royal palace in 1818 — and a sentry is said to have met her again that same night, a glass in her hand.","description":"Rosersberg Palace north of Stockholm is one of Sweden’s royal palaces, and Queen Hedvig Elisabet Charlotta died here in 1818. A family legend tells of a sentry at her coffin who heard footsteps across the empty floor and suddenly stood face to face with the dead queen, who in a hoarse voice held out a glass of a yellowish drink. The palace is a listed state monument with preserved late-Gustavian interiors and guided tours in summer."}}'::jsonb),
('sundbyholms-slott-sodermanland', 'Sundbyholms slott', 'sundbyholms-slott-sodermanland', 59.44778, 16.62389, 'Sverige', 'Södermanland, Eskilstuna', 'Slott', 3, false, true, 'Personalen kallar det Sörmlands spökrikaste slott – dörrar öppnas av sig själva och en svartklädd gestalt har setts i vinkällaren.', 'Sundbyholms slott vid Mälaren utanför Eskilstuna beskrivs ibland som Sörmlands spökrikaste slott. Personal och gäster har berättat om dörrar som öppnas och stängs på egen hand, nycklar som rasslar i tomma salar och handtag som trycks ner av sig själva. Efter en middag ska en lång, svartklädd gestalt med huva ha setts i vinkällaren. Ett medium lugnade enligt slottet med orden att här bara finns snälla spöken. I dag är Sundbyholm hotell och konferens vid Mälarens strand.', 'published', 'sundbyholms-slott', '{"en":{"name":"Sundbyholm Castle","teaser":"Staff call it Södermanland’s most haunted castle — doors open by themselves and a black-clad figure has been seen in the wine cellar.","description":"Sundbyholm Castle by Lake Mälaren outside Eskilstuna is sometimes called the most haunted castle in Södermanland. Staff and guests have told of doors that open and close on their own, keys rattling in empty halls and handles pressed down by unseen hands. After a dinner, a tall, black-clad hooded figure is said to have appeared in the wine cellar. A medium reportedly reassured the castle that only kind ghosts dwell here. Today Sundbyholm is a hotel and conference venue on the lakeshore."}}'::jsonb),
('wiks-slott-uppland', 'Wiks slott', 'wiks-slott-uppland', 59.73611, 17.46167, 'Sverige', 'Uppland, Uppsala', 'Slott', 4, false, true, 'En vit fru som drunknade på Mälarens is 1612 svävar här – och slår slottsuret tretton slag vaknar en fru ur 700 års sömn.', 'Wiks slott (Viks slott) i Uppland är en av Sveriges bäst bevarade medeltida borgar och har flera spöksägner. Den vita frun sägs vara Anna von der Grünau, som omkom på Mälarens is 1612; hon syns som en vitklädd kvinna svävande i dimman, med våta fotspår efter sig. Här talas också om en svart fru och om gamla fru Ramborg, som enligt sägnen vaknar ur sin 700-åriga sömn och visar sitt bleka ansikte i ett fönster de nätter slottsuret slår tretton slag. Slottet inrymmer folkhögskola och konferens och kan besökas.', 'published', 'regionuppsala', '{"en":{"name":"Wik Castle","teaser":"A White Lady who drowned on the lake ice in 1612 drifts here — and when the castle clock strikes thirteen, a lady wakes from 700 years of sleep.","description":"Wik Castle in Uppland is one of Sweden’s best-preserved medieval castles and holds several ghost legends. The White Lady is said to be Anna von der Grünau, who died on the ice of Lake Mälaren in 1612; she appears as a white-clad woman drifting through the mist, leaving wet footprints behind. There is also talk of a Black Lady and of old Lady Ramborg, who by legend wakes from her 700-year sleep and shows her pale face at a window on nights when the castle clock strikes thirteen. The castle houses a folk high school and conference venue and can be visited."}}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
  name=EXCLUDED.name, teaser=EXCLUDED.teaser, description=EXCLUDED.description,
  country=EXCLUDED.country, region=EXCLUDED.region, type=EXCLUDED.type,
  lat=EXCLUDED.lat, lng=EXCLUDED.lng, scary=EXCLUDED.scary,
  translations=EXCLUDED.translations, status=EXCLUDED.status, source=EXCLUDED.source;
COMMIT;

-- hauntedplaces-slott-no-2026-07-14.sql  (norska spökslott & herrgårdar, batch 1)
-- 2 nya platser till Hauntedplaces + Spökkartan (delat Supabase-projekt zffhdjogphqhcttkezsb).
-- Källa: 139 norska slott/herregårder/fort via Wikidata + no/nn-Wikipedia; spöksägner verifierade mot
-- minst en trovärdig källa (Wikipedia, museernas sidor, boken "Ekte gjenferd").
-- Deduplicerat mot 69 live norska platser (namn + koordinat <400 m). Norge var redan tungt täckt
-- (Akershus, Nidaros, Elingård, Rød m.fl. redan live) → få nya. Kvalitet före kvantitet.
-- Egen sv+en-text grundad i allmänt känd historia + folktro; källornas text återges ALDRIG ordagrant.
-- Idempotent: ON CONFLICT (id) DO UPDATE. Kör i Supabase SQL-editor (projekt zffhdjogphqhcttkezsb).

BEGIN;
INSERT INTO places (id, name, slug, lat, lng, country, region, type, scary, free, bookable, teaser, description, status, source, translations) VALUES
('fossesholm-herregard-buskerud', 'Fossesholm herregård', 'fossesholm-herregard-buskerud', 59.72811, 9.86642, 'Norge', 'Buskerud, Øvre Eiker', 'Herrgård', 3, false, true, 'På herrgården sägs Halte-Birthe gå igen – flickan som hånades för att hon bara kunde räkna till tre och kastade sig ut genom ett fönster.', 'Fossesholm herregård i Vestfossen är en av Norges bäst bevarade 1700-talsherrgårdar och i dag en del av Buskerudmuseet. Till gården hör sägnen om Halte-Birthe – Birthe Svendsdatter – som hånades för att hon bara kunde räkna till tre och som enligt berättelsen kastade sig ut genom ett fönster på övervåningen på 1700-talet. Sedan dess sägs hon vandra som ett haltande, olyckligt spöke på gården. Herrgården är öppen för besök med utställningar och trädgård.', 'published', 'wikipedia', '{"en":{"name":"Fossesholm Manor","teaser":"At this manor, ''Limping Birthe'' is said to walk — the girl mocked for counting only to three, who threw herself from a window.","description":"Fossesholm Manor in Vestfossen is one of Norway''s best-preserved 18th-century manors and today part of the Buskerud Museum. It carries the legend of Limping Birthe — Birthe Svendsdatter — mocked for being able to count only to three, who by tradition threw herself from an upstairs window in the 1700s. Since then she is said to wander the estate as a limping, unhappy ghost. The manor is open to visitors, with exhibitions and gardens."}}'::jsonb),
('austad-gard-drammen', 'Austad gård', 'austad-gard-drammen', 59.73, 10.2058, 'Norge', 'Buskerud, Drammen', 'Herrgård', 3, false, true, 'På herrgården i Drammen sägs den svarta damen gå igen – den stolta amtmannsfrun Ingeborg Marie Glud från tidigt 1700-tal.', 'Austad gård är en gammal herrgård i Drammen med anor tillbaka till 1600-talet. Till huset knyts sägnen om den svarta damen, som sägs vara Ingeborg Marie Glud – den stolta amtmannsfrun som styrde gården i början av 1700-talet. Hon ska ännu röra sig genom rummen, klädd i svart. Gården med sin park är i dag ett omtyckt utflyktsmål nära Drammensälven.', 'published', 'ekte-gjenferd', '{"en":{"name":"Austad Manor","teaser":"At this Drammen manor, the ''Black Lady'' is said to walk — Ingeborg Marie Glud, the proud governor''s wife of the early 1700s.","description":"Austad Manor is an old estate in Drammen with roots in the 17th century. The house carries the legend of the Black Lady, said to be Ingeborg Marie Glud — the proud governor''s wife who ruled the estate in the early 1700s. She is said to still move through the rooms, dressed in black. Today the manor and its park are a favourite outing near the Drammen River."}}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
  name=EXCLUDED.name, teaser=EXCLUDED.teaser, description=EXCLUDED.description,
  country=EXCLUDED.country, region=EXCLUDED.region, type=EXCLUDED.type,
  lat=EXCLUDED.lat, lng=EXCLUDED.lng, scary=EXCLUDED.scary,
  translations=EXCLUDED.translations, status=EXCLUDED.status, source=EXCLUDED.source;
COMMIT;

-- hauntedplaces-slott-dk-2026-07-14.sql  (danska spökslott & herrgårdar, batch 1)
-- 5 nya platser till Hauntedplaces + Spökkartan (delat Supabase-projekt zffhdjogphqhcttkezsb).
-- Källa: 794 danska slott/herregårder via Wikidata + da-Wikipedia; spöksägner verifierade mot minst
-- en trovärdig källa (Wikipedia, museer/slott, VisitFyn). Deduplicerat mot 54 live danska platser
-- OCH mot data/hauntedplaces-foreign-dk.sql (namn + koordinat <400 m). Dragsholm uteslöts —
-- fanns redan som 'dragsholm-slot-sjalland' i foreign-dk.sql. Egen sv+en-text; källornas text
-- återges ALDRIG ordagrant. Idempotent: ON CONFLICT (id) DO UPDATE.

BEGIN;
INSERT INTO places (id, name, slug, lat, lng, country, region, type, scary, free, bookable, teaser, description, status, source, translations) VALUES
('voergaard-slot-vendsyssel', 'Voergaard Slot', 'voergaard-slot-vendsyssel', 57.2425, 10.3354, 'Danmark', 'Jylland, Vendsyssel', 'Slott', 4, false, true, 'Den hårda slottsfrun Ingeborg Skeel sägs ännu återvända till renässansslottet i Vendsyssel.', 'Voergaard Slot i Vendsyssel är ett av Danmarks vackraste renässansslott, färdigt 1588. Dess mest omtalade spöke är Ingeborg Skeel, den hårda slottsfrun som av sina bönder upplevdes som en tyrann och som enligt sägnen återvänder till slottet gång på gång. Den långa raden av ägare och de mörka gångarna ger platsen en stämning av gången tid. Slottet rymmer i dag en konstsamling och är öppet för besök.', 'published', 'wikipedia', '{"en":{"name":"Voergaard Castle","teaser":"The hard mistress Ingeborg Skeel is still said to return to this Renaissance castle in Vendsyssel.","description":"Voergaard Castle in Vendsyssel is one of Denmark’s finest Renaissance castles, completed in 1588. Its most talked-about ghost is Ingeborg Skeel, the stern lady of the house whom her tenants experienced as a tyrant and who by legend returns to the castle again and again. The long line of owners and the dark passages lend the place an air of ages past. Today the castle holds an art collection and is open to visitors."}}'::jsonb),
('egeskov-slot-fyn', 'Egeskov Slot', 'egeskov-slot-fyn', 55.17639, 10.48944, 'Danmark', 'Fyn', 'Slott', 3, false, true, 'En liten trädocka måste få färsk halm varje jul – annars sägs slottet sjunka i vallgraven. Och en vit dam vandrar i parken.', 'Egeskov Slot på Fyn är en av Europas bäst bevarade vattenborgar, byggd mitt i en sjö på 1550-talet. Sägnen säger att en liten trädocka på tornvinden måste få färsk halm varje lillajulafton – annars sjunker slottet i vallgraven på julafton. Här går också en vit dam: en ung brud som drunknade i sjön när hästarna skenade och som sägs söka sin fästman i parken efter mörkrets inbrott. Slottet med sina trädgårdar och museer är ett av Danmarks mest besökta.', 'published', 'wikipedia', '{"en":{"name":"Egeskov Castle","teaser":"A little wooden figure must get fresh straw each Christmas — or the castle is said to sink into the moat. And a White Lady walks the park.","description":"Egeskov Castle on Funen is one of Europe’s best-preserved moated castles, built in the middle of a lake in the 1550s. Legend says a small wooden figure in the tower loft must be given fresh straw every Little Christmas Eve — or the castle will sink into the moat on Christmas Eve. A White Lady walks here too: a young bride who drowned in the lake when the horses bolted, said to search the park for her betrothed after dark. With its gardens and museums, the castle is one of Denmark’s most visited."}}'::jsonb),
('krenkerup-lolland', 'Krenkerup', 'krenkerup-lolland', 54.7769, 11.6703, 'Danmark', 'Lolland', 'Herrgård', 3, false, true, 'Det lolländska godset sägs hemsökas av en vit dam och av adelsmannen Palle Rosenkrantz gengångare.', 'Krenkerup är ett av Lollands största gods, med anor från medeltiden. Enligt traditionen hemsöks godset av flera gengångare – bland dem en vit dam och adelsmannen Palle Rosenkrantz. De gamla salarna och den vidsträckta parken ger platsen en stämning av svunna sekler. Godset är fortfarande i släkten Haugwitz-Hardenberg-Reventlows ägo.', 'published', 'wikipedia', '{"en":{"name":"Krenkerup","teaser":"This Lolland estate is said to be haunted by a White Lady and by the ghost of the nobleman Palle Rosenkrantz.","description":"Krenkerup is one of the largest estates on Lolland, with roots in the Middle Ages. By tradition the estate is haunted by several revenants — among them a White Lady and the nobleman Palle Rosenkrantz. The old halls and sweeping park lend the place the mood of vanished centuries. The estate remains in the Haugwitz-Hardenberg-Reventlow family."}}'::jsonb),
('irup-thy', 'Irup', 'irup-thy', 56.83344, 8.52999, 'Danmark', 'Jylland, Thy', 'Herrgård', 3, false, true, 'Vid fullmåne – helst en torsdag – sägs den vita damen ta en promenad genom parken på Irup.', 'Irup är en gammal herrgård i Thy på nordvästra Jylland. Många sägner är knutna till gården, och liksom flera danska herregårdar har Irup sin vita dam: vid fullmåne, helst en torsdag, sägs hon gå en tur genom parken ner mot vattnet. Gården är känd för sin långa historia och sitt goda jordbruk.', 'published', 'wikipedia', '{"en":{"name":"Irup Manor","teaser":"At full moon — best on a Thursday — the White Lady is said to take a walk through the park at Irup.","description":"Irup is an old manor in Thy in north-western Jutland. Many legends cling to the estate, and like several Danish manors Irup has its White Lady: at full moon, best on a Thursday, she is said to walk down through the park toward the water. The farm is known for its long history and fine agriculture."}}'::jsonb),
('starup-hovedgard-salling', 'Stårup Hovedgård', 'starup-hovedgard-salling', 56.5864, 9.11139, 'Danmark', 'Jylland, Salling', 'Herrgård', 3, false, true, 'På den gamla jyska herrgården sägs den grå damen gå igen – ett av gårdens många genfärd.', 'Stårup Hovedgård är en gammal herrgård i Salling på Jylland med rötter långt tillbaka i tiden. Som på så många danska herregårdar knyts spöksägner till huset – här berättas särskilt om den grå damen, ett genfärd som sägs röra sig genom de gamla rummen. Gården har genom seklen gått mellan olika släkter innan jorden styckades under 1900-talet.', 'published', 'wikipedia', '{"en":{"name":"Stårup Manor","teaser":"At this old Jutland manor the Grey Lady is said to walk — one of the estate’s many revenants.","description":"Stårup Manor is an old estate in Salling, Jutland, with roots far back in time. As at so many Danish manors, ghost legends cling to the house — here especially the Grey Lady, a revenant said to move through the old rooms. Over the centuries the estate passed between families before its land was parcelled out in the 1900s."}}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
  name=EXCLUDED.name, teaser=EXCLUDED.teaser, description=EXCLUDED.description,
  country=EXCLUDED.country, region=EXCLUDED.region, type=EXCLUDED.type,
  lat=EXCLUDED.lat, lng=EXCLUDED.lng, scary=EXCLUDED.scary,
  translations=EXCLUDED.translations, status=EXCLUDED.status, source=EXCLUDED.source;
COMMIT;

-- hauntedplaces-slott-fi-2026-07-14.sql  (finska spökslott & herrgårdar, batch 1)
-- 4 nya platser till Hauntedplaces + Spökkartan (delat Supabase-projekt zffhdjogphqhcttkezsb).
-- Källa: 252 finska slott/kartanot via Wikidata + fi/sv-Wikipedia; spöksägner verifierade mot minst
-- en trovärdig källa (Wikipedia, Kansallismuseo, Kotiliesi/Yle/Apu, VisitSavonlinna). Deduplicerat
-- mot live (1 finsk: Suomenlinna) + data/hauntedplaces-foreign-fi.sql (Helsingfors). Finland var
-- nästan otäckt → 4 flaggskepp. Egen sv+en-text; källornas text återges ALDRIG ordagrant.
-- Idempotent: ON CONFLICT (id) DO UPDATE. Kör i Supabase SQL-editor (projekt zffhdjogphqhcttkezsb).

BEGIN;
INSERT INTO places (id, name, slug, lat, lng, country, region, type, scary, free, bookable, teaser, description, status, source, translations) VALUES
('olavinlinna-savonlinna', 'Olavinlinna (Olofsborg)', 'olavinlinna-savonlinna', 61.8637134, 28.9012379, 'Finland', 'Södra Savolax, Savonlinna', 'Slott', 4, false, true, 'På medeltidsborgen sägs en jungfru, inmurad levande, visa sig på balkongen vid fullmåne – och en vetehinen spelade harpa före varje olycka.', 'Olavinlinna (Olofsborg) reser sig på en holme i Saimen vid Nyslott och är en av Nordens bäst bevarade medeltidsborgar. Slottets mest kända sägen berättar om en ung slottsjungfru som straffades för förräderi genom att muras in levande – vid midnatt under fullmåne sägs hon och hennes officer synas på borgens balkong. Hit hör också berättelsen om den svarta baggen som skrämde bort en fiende och om vetehinen, vattenanden som spelade harpa varje gång en olycka eller plötslig död var i annalkande. Borgen är museum och spelplats för operafestivalen.', 'published', 'wikipedia', '{"en":{"name":"Olavinlinna Castle","teaser":"At this medieval fortress a maiden walled up alive is said to appear on the balcony at full moon — and a water spirit played the harp before every disaster.","description":"Olavinlinna (Olofsborg) rises on an islet in Lake Saimaa at Savonlinna and is one of the Nordic region''s best-preserved medieval castles. Its most famous legend tells of a young castle maiden walled up alive for treachery — at midnight under a full moon she and her officer are said to appear on the castle balcony. There is also the tale of the black ram that scared off an enemy, and of the vetehinen, the water spirit who played the harp whenever disaster or sudden death drew near. The castle is a museum and the stage for the opera festival."}}'::jsonb),
('svarta-slott-mustio-raseborg', 'Svartå slott (Mustion linna)', 'svarta-slott-mustio-raseborg', 60.1579988, 23.8389826, 'Finland', 'Nyland, Raseborg', 'Slott', 4, false, true, 'Den vita frun vandrar med en kandelaber genom rummen, kung Gustav III släpar sina steg i kungsgemaket, och en grå fru skymtar på tredje våningen.', 'Svartå slott (Mustion linna) i Raseborg är ett av Finlands vackraste herrgårdsslott, byggt i nyklassicistisk stil på 1780-talet. Enligt traditionen har slottet fyra spöken. Mest känd är den vita frun som vandrar från rum till rum med en kandelaber – hon kopplas till Jeanette Hisinger, som sägs ha lidit av psykisk ohälsa och hållits inlåst på övervåningen. Kung Gustav III sägs hemsöka kungsgemaket med trötta, släpande steg, och på tredje våningen skymtar en grå fru vars profil setts mot de vita väggarna. Slottet med sin engelska park är öppet för besök.', 'published', 'wikipedia', '{"en":{"name":"Svartå Manor (Mustio)","teaser":"The White Lady wanders the rooms with a candelabra, King Gustav III drags his steps in the royal chamber, and a Grey Woman haunts the third floor.","description":"Svartå Manor (Mustion linna) in Raseborg is one of Finland''s finest manor-castles, built in neoclassical style in the 1780s. By tradition the house has four ghosts. Best known is the White Lady who wanders room to room with a candelabra — linked to Jeanette Hisinger, said to have suffered mental illness and been kept locked upstairs. King Gustav III is said to haunt the royal chamber with weary, dragging steps, and on the third floor a Grey Woman appears, her profile seen against the white walls. The manor and its English park are open to visitors."}}'::jsonb),
('louhisaari-kartano-masku', 'Louhisaari (Louhisaaren kartano)', 'louhisaari-kartano-masku', 60.570916666667, 21.831055555556, 'Finland', 'Egentliga Finland, Masku', 'Herrgård', 4, false, true, 'En svartsjuk make glömde att säga att han låst in sin hustru – hon svalt ihjäl, och den vita frun vandrar än på tredje våningen, ibland med ett barn.', 'Louhisaari (Louhisaaren kartano) i Masku är marskalk Mannerheims barndomshem och en av Finlands få herrgårdar i palatsstil, uppförd på 1650-talet. Sägnen berättar om Anna Sophia Rehbinder, hustru till den svartsjuke Herman Fleming som brukade låsa in henne när han reste bort. En gång glömde han säga till tjänarna – och hon svalt ihjäl. Sedan dess sägs den vita frun vandra på tredje våningen, ofta i sällskap av ett barn som ingen vet vem det är. Besökare har berättat om föremål som flyttar sig, dörrar som öppnas och doften av cigarrök. Herrgården är museum.', 'published', 'wikipedia', '{"en":{"name":"Louhisaari Manor","teaser":"A jealous husband forgot he''d locked his wife away — she starved to death, and the White Lady still walks the third floor, sometimes with a child.","description":"Louhisaari Manor (Louhisaaren kartano) in Masku is Marshal Mannerheim''s childhood home and one of Finland''s few palace-style manors, built in the 1650s. Legend tells of Anna Sophia Rehbinder, wife of the jealous Herman Fleming, who used to lock her away when he travelled. Once he forgot to tell the servants — and she starved to death. Since then the White Lady is said to walk the third floor, often with a child no one can identify. Visitors have described objects that move, doors that open and the scent of cigar smoke. The manor is a museum."}}'::jsonb),
('abo-slott-turku', 'Åbo slott (Turun linna)', 'abo-slott-turku', 60.4352823, 22.2276388, 'Finland', 'Egentliga Finland, Åbo', 'Slott', 3, false, true, 'Nästan alla som arbetat länge på borgen sägs ha sett ett spöke – en man i tidsdräkt i trapporna, och en grönskimrande kvinna med slöja.', 'Åbo slott (Turun linna) vid Aura ås mynning är Finlands största medeltidsborg, grundad på 1280-talet. Många som arbetat länge på borgen säger sig ha sett spöken: på 1980-talet såg både en städare och slottets vaktmästare en man i historisk dräkt i trappan vid fångvaktarens rum. Andra berättar om en grönskimrande kvinnogestalt med slöja, tolkad som en brud eller nunna. En gammal sägen säger att en man murades in levande i en mur som restes under Gustav Vasas tid. Borgen är i dag ett av Finlands mest besökta museer.', 'published', 'wikipedia', '{"en":{"name":"Turku Castle","teaser":"Nearly everyone who has worked here for long is said to have seen a ghost — a man in period dress on the stairs, and a green-shimmering veiled woman.","description":"Turku Castle (Turun linna) at the mouth of the Aura River is Finland''s largest medieval castle, founded in the 1280s. Many long-serving staff say they have seen ghosts: in the 1980s both a cleaner and the castle caretaker saw a man in historical dress on the stairs by the prison guard''s room. Others tell of a green-shimmering veiled female figure, taken for a bride or a nun. An old legend holds that a man was walled up alive in a wall raised in the time of Gustav Vasa. Today the castle is one of Finland''s most visited museums."}}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
  name=EXCLUDED.name, teaser=EXCLUDED.teaser, description=EXCLUDED.description,
