COMMIT;

-- hauntedplaces-herrgardar-se-2026-07-14.sql  (svenska hemsökta herrgårdar, ANDRA varvet)
-- 4 nya platser till Hauntedplaces + Spökkartan (delat Supabase-projekt zffhdjogphqhcttkezsb).
-- Dedikerat herrgårds-andravarv: webbsök/listkällor per herrgård (Wikipedia missar sägnerna).
-- Deduplicerat mot 1305 live-platser (namn OCH koordinat) + SQL-filerna. De flesta kända svenska
-- herrgårdar var REDAN live (wordpress-importen): Österbybruk, Ericsberg/Pintorpafrun, Toftaholm,
-- Hörle, Blombacka, Blomsholm, Hammars säteri, Görväln (namn-match 1085 m) → uteslutna.
-- Egen sv+en-text; källornas text återges ALDRIG ordagrant. Idempotent: ON CONFLICT (id) DO UPDATE.

BEGIN;
INSERT INTO places (id, name, slug, lat, lng, country, region, type, scary, free, bookable, teaser, description, status, source, translations) VALUES
('von-echstedtska-garden-varmland', 'Von Echstedtska gården', 'von-echstedtska-garden-varmland', 59.2278, 12.7313, 'Sverige', 'Värmland, Säffle', 'Herrgård', 3, false, true, 'Pigan kastade nyckeln mot det vitklädda spöket i farstun – och dödade drängen som ville skrämmas. Hon blev vansinnig och sägs gå igen.', 'Von Echstedtska gården i Västra Smedbyn norr om Säffle är en välbevarad herrgård från 1760-talet, känd för sina takmålningar – och för sin spöksägen. En kväll när pigan låste visthusboden möttes hon i farstun av en vitklädd gestalt med lysande huvud. I skräck kastade hon den tunga nyckeln med all kraft, och gestalten föll ihop. Det visade sig vara drängen, som klätt ut sig i ett vitt lakan med en tändsticka i munnen för att skrämmas. Pigan förlorade förståndet, spärrades in i en flygel och dog där, och sägs sedan dess inte finna ro. Gården är i dag museum.', 'published', 'varmlands-museum', '{"en":{"name":"Von Echstedt Manor","teaser":"The maid hurled the key at the white-clad ghost in the hall — and killed the farmhand who meant to scare her. She lost her mind, and is said to walk still.","description":"Von Echstedt Manor at Västra Smedbyn north of Säffle is a well-preserved 1760s manor famous for its ceiling paintings — and for its ghost legend. One evening as the maid locked the storehouse, she met a white-clad figure with a glowing head in the hall. In terror she hurled the heavy key with all her strength, and the figure collapsed. It was the farmhand, dressed in a white sheet with a match in his mouth to frighten her. The maid lost her mind, was locked in a wing and died there, and since then is said to find no peace. The manor is a museum today."}}'::jsonb),
('noors-slott-knivsta', 'Noors slott', 'noors-slott-knivsta', 59.71611, 17.81972, 'Sverige', 'Uppland, Knivsta', 'Slott', 3, false, true, 'När Heidenstam skrev om Karl XII:s död sägs kungen själv ha stigit fram i dörröppningen – i fältuniform, klockan två på natten.', 'Noors slott är en herrgård från karolinertiden i Knivsta, Uppland. Dess mest kända spökhistoria är kopplad till författaren Verner von Heidenstam, som bodde här ett helt år medan han skrev Karolinerna. En natt vid tvåtiden, just som han avslutade kapitlet om Karl XII:s död vid Fredrikshald, hörde han steg och ett pinglande, skramlande ljud – och i den mörka dörröppningen stod, enligt hans egen skildring, kung Karl XII själv i fältuniform. Slottet är i dag hotell och konferens.', 'published', 'wikipedia', '{"en":{"name":"Noor Castle","teaser":"As Heidenstam wrote of Karl XII’s death, the king himself is said to have stepped into the doorway — in field uniform, at two in the morning.","description":"Noor Castle is a Carolean-era manor in Knivsta, Uppland. Its most famous ghost story involves the writer Verner von Heidenstam, who lived here for a year while writing The Charles Men (Karolinerna). One night around two, just as he finished the chapter on Karl XII’s death at Fredrikshald, he heard footsteps and a jingling, rattling sound — and in the dark doorway stood, by his own account, King Karl XII himself in field uniform. The castle is a hotel and conference venue today."}}'::jsonb),
('gimo-herrgard-uppland', 'Gimo herrgård', 'gimo-herrgard-uppland', 60.17889, 18.17364, 'Sverige', 'Uppland, Östhammar', 'Herrgård', 3, false, true, 'En iskall vind, en dörr som öppnas av sig själv och biljardköer utspridda över golvet – på Gimo sägs drängen Johansson gå igen.', 'Gimo herrgård i Uppland, med huvudbyggnad från 1760-talet, har som sig bör sitt eget spöke. Sägnen utpekar en dräng vid namn Johansson, anställd hos brukspatronen Carl Reuterskiöld på 1800-talet. Personal har berättat om en iskall vind som plötsligt drog genom ett rum strax efter klockan åtta medan dörren till spiraltrappan öppnade sig av sig själv, om släpande steg som följer från rum till rum och om en svart gestalt som glidit förbi och antagit mänsklig form. En gång låg biljardköerna utslängda över golvet. Herrgården är i dag hotell och konferens.', 'published', 'wikipedia', '{"en":{"name":"Gimo Manor","teaser":"An icy wind, a door that opens by itself and billiard cues strewn across the floor — at Gimo the farmhand Johansson is said to walk.","description":"Gimo Manor in Uppland, with a main building from the 1760s, has — as a proper manor should — its own ghost. Legend names a farmhand called Johansson, employed by the ironmaster Carl Reuterskiöld in the 1800s. Staff have told of an icy wind that suddenly swept through a room just after eight while the door to the spiral staircase opened on its own, of dragging footsteps that follow from room to room, and of a black figure that glided past and took human form. Once the billiard cues lay scattered across the floor. The manor is a hotel and conference venue today."}}'::jsonb),
('rankhyttans-herrgard-dalarna', 'Rankhyttans herrgård', 'rankhyttans-herrgard-dalarna', 60.47611, 15.71972, 'Sverige', 'Dalarna, Falun', 'Herrgård', 3, false, true, 'Bergsmannen halshöggs 1534 – och hans hustru sägs ännu vandra som den svarta damen i herrgården.', 'Rankhyttans herrgård utanför Falun i Dalarna vilar på ett gråstensvalv från medeltiden och ägdes under 1500-talets första hälft av bergsmannen Anders Persson. Anders halshöggs i Stockholm 1534, och sägnen berättar att det är hans hustru som går igen i herrgården under namnet den svarta damen. Flera spöken sägs hålla till i de gamla rummen. Herrgården används i dag för konferens och fest.', 'published', 'spokhus', '{"en":{"name":"Rankhyttan Manor","teaser":"The mining master was beheaded in 1534 — and his wife is said to still walk the manor as the Black Lady.","description":"Rankhyttan Manor outside Falun in Dalarna rests on a medieval greystone vault and was owned in the early 1500s by the mining master Anders Persson. Anders was beheaded in Stockholm in 1534, and legend holds that it is his wife who walks the manor as the Black Lady. Several ghosts are said to dwell in the old rooms. The manor is used today for conferences and celebrations."}}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
  name=EXCLUDED.name, teaser=EXCLUDED.teaser, description=EXCLUDED.description,
  country=EXCLUDED.country, region=EXCLUDED.region, type=EXCLUDED.type,
  lat=EXCLUDED.lat, lng=EXCLUDED.lng, scary=EXCLUDED.scary,
  translations=EXCLUDED.translations, status=EXCLUDED.status, source=EXCLUDED.source;
COMMIT;

-- hauntedplaces-slott-uk-2026-07-14.sql  (kända brittiska spökslott, batch 1)
-- 12 nya platser till Hauntedplaces + Spökkartan (delat Supabase-projekt zffhdjogphqhcttkezsb).
-- Kurerade ur den notabla utländska delmängden (data/enrichment-source-notable-foreign.json).
-- Varje sägen webbverifierad mot flera källor (Wikipedia, hauntedrooms.co.uk, spookyisles m.fl.).
-- Dedup mot 1305 live (namn OCH koordinat <500 m): Berry Pomeroy (96 m) och Edinburgh Castle
-- (25 m från befintlig Witches' Well-pin) uteslutna. Egen sv+en-text; källtext återges ALDRIG.
-- Landsetikett 'UK' (matchar appens live-data). Idempotent: ON CONFLICT (id) DO UPDATE.

BEGIN;
INSERT INTO places (id, name, slug, lat, lng, country, region, type, scary, free, bookable, teaser, description, status, source, translations) VALUES
('chillingham-castle-northumberland', 'Chillingham Castle', 'chillingham-castle-northumberland', 55.5258989, -1.9039315, 'UK', 'Northumberland', 'Slott', 5, false, true, 'Den lysande blå pojken grät vid midnatt i Rosa rummet – och vid en renovering hittades barnben inmurade i väggen, svepta i blått tyg.', 'Chillingham Castle i Northumberland kallas ofta Storbritanniens mest hemsökta slott. Dess mest kända spöke är den lysande blå pojken, vars klagande rop hördes vid midnatt i Rosa rummet, följt av ett blått sken. Vid en renovering på 1900-talet fann arbetare barnben inmurade i väggen, svepta i blått tyg. Här sägs också Lady Mary Berkeley vandra, och slottets fängelsehålor bär på en mörk historia.', 'published', 'wikipedia', '{"en":{"name":"Chillingham Castle","teaser":"The radiant Blue Boy cried at midnight in the Pink Room — and a renovation uncovered a child’s bones walled up in blue cloth.","description":"Chillingham Castle in Northumberland is often called Britain’s most haunted castle. Its best-known ghost is the radiant Blue Boy, whose mournful cries were heard at midnight in the Pink Room, followed by a blue glow. During a 20th-century renovation, workers found a child’s bones walled up and wrapped in blue cloth. Lady Mary Berkeley is also said to walk here, and the castle’s dungeons carry a dark history."}}'::jsonb),
('glamis-castle-angus', 'Glamis Castle', 'glamis-castle-angus', 56.620331, -3.001816, 'UK', 'Angus, Skottland', 'Slott', 5, false, true, 'Earl Beardie sägs spela kort med djävulen i ett hemligt rum – och slottet gömmer sägnen om Monstret på Glamis.', 'Glamis Castle i Angus är ett av Skottlands mest sägenomspunna slott. Här sägs Earl Beardie sitta i ett hemligt, igenmurat rum och spela kort med djävulen i evighet, sedan han svurit att spela på sabbaten. Slottet bär också på legenden om Monstret på Glamis, ett vanskapt familjebarn som enligt sägnen hölls dolt, samt om en grå dam som setts i kapellet. Slottet är drottningmoderns barndomshem.', 'published', 'wikipedia', '{"en":{"name":"Glamis Castle","teaser":"Earl Beardie is said to play cards with the Devil in a secret room — and the castle hides the legend of the Monster of Glamis.","description":"Glamis Castle in Angus is one of Scotland’s most legend-haunted castles. Earl Beardie is said to sit in a secret, walled-up room playing cards with the Devil for eternity, after swearing to play on the Sabbath. The castle also carries the legend of the Monster of Glamis, a deformed family child said to have been hidden away, and of a Grey Lady seen in the chapel. It was the childhood home of the Queen Mother."}}'::jsonb),
('muncaster-castle-cumbria', 'Muncaster Castle', 'muncaster-castle-cumbria', 54.3546391, -3.3807014, 'UK', 'Cumbria', 'Slott', 4, false, true, 'I gobelängrummet hörs ett gråtande barn och en sjungande kvinna – och Vita damen sägs vara Mary Bragg, mördad vid slottsporten på 1800-talet.', 'Muncaster Castle i Cumbria är ett vallfärdsmål för spökforskare. I det så kallade gobelängrummet berättar besökare om ett gråtande barn och en sjungande kvinna. Slottets vita dam sägs vara Mary Bragg, en ung kvinna som mördades nära huvudporten i början av 1800-talet. Slottet, som ännu bebos av familjen Pennington, är öppet för besök.', 'published', 'wikipedia', '{"en":{"name":"Muncaster Castle","teaser":"A crying child and a singing woman are heard in the Tapestry Room — and the White Lady is said to be Mary Bragg, murdered by the gate in the 1800s.","description":"Muncaster Castle in Cumbria is a magnet for paranormal researchers. In the Tapestry Room, visitors report a crying child and a singing woman. The castle’s White Lady is said to be Mary Bragg, a young woman murdered near the main gate in the early 1800s. Still home to the Pennington family, the castle is open to visitors."}}'::jsonb),
('warwick-castle-warwickshire', 'Warwick Castle', 'warwick-castle-warwickshire', 52.2795271, -1.5844827, 'UK', 'Warwickshire', 'Slott', 4, false, true, 'Sir Fulke Greville knivhöggs av sin tjänare 1628 – och sägs ännu vandra i Watergate-tornet där han dog.', 'Warwick Castle är ett av Englands mäktigaste medeltidsslott. Dess mest kända spöke är Sir Fulke Greville, en tidigare slottsherre som 1628 knivhöggs till döds av sin tjänare Ralph Haywood i en tvist om testamentet. Sedan dess sägs hans vålnad vandra genom slottet, särskilt i Watergate-tornet – i dag kallat Ghost Tower – där han tillbringade sina sista plågsamma dygn.', 'published', 'wikipedia', '{"en":{"name":"Warwick Castle","teaser":"Sir Fulke Greville was stabbed by his servant in 1628 — and is said to still walk the Watergate Tower where he died.","description":"Warwick Castle is one of England’s mightiest medieval castles. Its best-known ghost is Sir Fulke Greville, a former lord of the castle stabbed to death in 1628 by his servant Ralph Haywood in a dispute over his will. Since then his apparition is said to wander the castle, especially the Watergate Tower — today called the Ghost Tower — where he spent his last agonising days."}}'::jsonb),
('tutbury-castle-staffordshire', 'Tutbury Castle', 'tutbury-castle-staffordshire', 52.8597616, -1.6903381, 'UK', 'Staffordshire', 'Slott', 4, false, true, 'Maria Stuart hölls fången här och sägs gå igen – 2004 ska hon ha visat sig för ett fyrtiotal personer på södra tornet.', 'Tutbury Castle i Staffordshire var ett av de fängelser där Maria Stuart hölls inspärrad. Hon sägs avsky platsen och gå igen som ett av slottets spöken. Här berättas också om en gestalt i full rustning, en vit dam och ett barn. År 2004 ska Marias vålnad ha visat sig för ett fyrtiotal personer på södra tornet. Ruinen är öppen för besök.', 'published', 'wikipedia', '{"en":{"name":"Tutbury Castle","teaser":"Mary Queen of Scots was imprisoned here and is said to walk — in 2004 her apparition reportedly appeared to some forty people on the South Tower.","description":"Tutbury Castle in Staffordshire was one of the prisons where Mary Queen of Scots was held. She is said to despise the place and to return as one of its ghosts. There are also accounts of a figure in full armour, a White Lady and a child. In 2004 Mary’s apparition reportedly appeared to some forty people atop the South Tower. The ruin is open to visitors."}}'::jsonb),
('dover-castle-kent', 'Dover Castle', 'dover-castle-kent', 51.1289759, 1.3228764, 'UK', 'Kent', 'Slott', 4, false, true, 'En huvudlös trumslagarpojke sägs vandra i tunnlarna – mördad och halshuggen medan han bar en summa pengar.', 'Dover Castle i Kent, "nyckeln till England", vilar på ett nät av tunnlar. Dess mest kända spöke är en huvudlös trumslagarpojke som enligt sägnen mördades och halshöggs medan han bar en summa pengar genom gångarna. Hans trumslag hörs ännu från vallarna. Slottet är ett av Englands mest omtalade hemsökta.', 'published', 'wikipedia', '{"en":{"name":"Dover Castle","teaser":"A headless drummer boy is said to walk the tunnels — murdered and beheaded while carrying a sum of money.","description":"Dover Castle in Kent, \"the key to England\", rests on a web of tunnels. Its most famous ghost is a headless drummer boy who, by legend, was murdered and beheaded while carrying a sum of money through the passages. His drumming is still heard on the battlements. The castle is one of England’s most talked-about haunted sites."}}'::jsonb),
('bamburgh-castle-northumberland', 'Bamburgh Castle', 'bamburgh-castle-northumberland', 55.609444, -1.7112671, 'UK', 'Northumberland', 'Slott', 3, false, true, 'Gröna Jane skickades att tigga mat, visades bort och föll död med sitt barn i famnen – ännu sägs hon vandra vid slottet.', 'Bamburgh Castle reser sig dramatiskt över Northumberlands kust. Slottets gröna dam, kallad Gröna Jane, sägs vara en fattig flicka som skickades att tigga mat vid slottet men visades bort av vakterna. Utmattad föll hon till sin död med sitt spädbarn i famnen. Här berättas också om en rosa dam, slottets äldsta spöke. Borgen är öppen för besök.', 'published', 'wikipedia', '{"en":{"name":"Bamburgh Castle","teaser":"Green Jane was sent to beg for food, turned away, and fell to her death with her baby — she is still said to walk the castle.","description":"Bamburgh Castle rises dramatically above the Northumberland coast. Its Green Lady, called Green Jane, is said to be a poor girl sent to beg for food at the castle but turned away by the guards. Exhausted, she fell to her death with her infant in her arms. There is also a Pink Lady, the castle’s oldest ghost. The fortress is open to visitors."}}'::jsonb),
('stirling-castle-stirling', 'Stirling Castle', 'stirling-castle-stirling', 56.123717, -3.947873, 'UK', 'Stirling, Skottland', 'Slott', 3, false, true, 'Att se Gröna damen sägs varsla om eld – hon var tjänarinna åt Maria Stuart och dog själv i en brand.', 'Stirling Castle, ett av Skottlands största slott, hemsöks enligt traditionen av Gröna damen. Hon sägs ha varit tjänarinna åt Maria Stuart, och att se henne varslar om eld eller olycka – enligt sägnen dog hon själv i en brand. Här går också en rosa dam. Slottet, där flera skotska kungar krönts, är öppet för besök.', 'published', 'wikipedia', '{"en":{"name":"Stirling Castle","teaser":"Seeing the Green Lady is said to warn of fire — she was a maid to Mary Queen of Scots and died in a blaze.","description":"Stirling Castle, one of Scotland’s largest, is by tradition haunted by the Green Lady. She is said to have been a maid to Mary Queen of Scots, and seeing her warns of fire or disaster — by legend she herself died in a blaze. A Pink Lady walks here too. The castle, where several Scottish kings were crowned, is open to visitors."}}'::jsonb),
('tamworth-castle-staffordshire', 'Tamworth Castle', 'tamworth-castle-staffordshire', 52.6325994, -1.6967458, 'UK', 'Staffordshire', 'Slott', 3, false, true, 'Svarta damen sägs vara nunnan Editha, vars kloster fördrevs – och en vit dam vandrar och söker sin mördade älskade.', 'Tamworth Castle har två kända spöken. Svarta damen sägs vara nunnan Editha, som grundade sin orden på 800-talet och vars systrar enligt sägnen fördrevs från klostret av Robert de Marmion. Vita damen ska ha kastats i tornet av Sir Tarquin, förälskat sig i honom, och vandrar nu och söker sin älskade. Den välbevarade normandiska borgen är i dag museum.', 'published', 'wikipedia', '{"en":{"name":"Tamworth Castle","teaser":"The Black Lady is said to be the nun Editha, whose convent was expelled — and a White Lady walks seeking her murdered love.","description":"Tamworth Castle has two well-known ghosts. The Black Lady is said to be the nun Editha, who founded her order in the 9th century and whose sisters were, by legend, expelled from their convent by Robert de Marmion. The White Lady was reputedly thrown into the tower by Sir Tarquin, fell in love with him, and now walks seeking her lost love. The well-preserved Norman castle is a museum today."}}'::jsonb),
('dudley-castle-west-midlands', 'Dudley Castle', 'dudley-castle-west-midlands', 52.5145004, -2.0790075, 'UK', 'West Midlands', 'Slott', 3, false, true, 'Gråa damen sägs vara Dorothy Beaumont, död strax efter en förlossning – hennes sista önskningar uppfylldes aldrig.', 'Dudley Castle i West Midlands hemsöks enligt traditionen av Gråa damen, som sägs vara Dorothy Beaumont. Hon dog strax efter att ha fött barn på slottet och sägs inte finna ro, eftersom de önskningar hon uttalade på sin dödsbädd aldrig uppfylldes. En besökare påstod sig ha fångat henne på bild. Slottet ligger i dag inom Dudley djurpark.', 'published', 'wikipedia', '{"en":{"name":"Dudley Castle","teaser":"The Grey Lady is said to be Dorothy Beaumont, dead soon after childbirth — her dying wishes never granted.","description":"Dudley Castle in the West Midlands is by tradition haunted by the Grey Lady, said to be Dorothy Beaumont. She died soon after giving birth at the castle and is said to find no rest, because the wishes she voiced on her deathbed were never granted. One visitor claimed to have caught her on camera. The castle today lies within Dudley Zoo."}}'::jsonb),
('windsor-castle-berkshire', 'Windsor Castle', 'windsor-castle-berkshire', 51.4837886, -0.6040419, 'UK', 'Berkshire', 'Slott', 3, false, true, 'Anne Boleyns vålnad sägs synas i fönstren – och i den kringliggande parken rider den spöklike Herne the Hunter.', 'Windsor Castle, den brittiska monarkins äldsta bebodda slott, bär på flera spöksägner. Anne Boleyn, halshuggen av Henrik VIII, sägs synas i fönstren, och kungen själv ska höras släpa sina steg genom korridorerna. I Windsor Great Park rider enligt sägnen Herne the Hunter, en spöklik jägare med hjorthorn vars uppenbarelse varslar om olycka.', 'published', 'wikipedia', '{"en":{"name":"Windsor Castle","teaser":"Anne Boleyn’s apparition is said to appear at the windows — and in the surrounding park rides the ghostly Herne the Hunter.","description":"Windsor Castle, the oldest inhabited castle of the British monarchy, carries several ghost legends. Anne Boleyn, beheaded by Henry VIII, is said to appear at the windows, and the king himself is said to be heard dragging his steps through the corridors. In Windsor Great Park, legend has it, rides Herne the Hunter, a spectral huntsman with antlers whose appearance warns of misfortune."}}'::jsonb),
('highclere-castle-berkshire', 'Highclere Castle', 'highclere-castle-berkshire', 51.4100297, -1.3044986, 'UK', 'Berkshire', 'Slott', 3, false, true, 'På slottet som spelar Downton Abbey sägs en olycklig betjänt gå igen – ägaren själv har berättat om spöken.', 'Highclere Castle i Berkshire är känt som inspelningsplats för Downton Abbey. Slottet, hem för familjen Carnarvon – vars femte earl var med och öppnade Tutankhamuns grav 1922 – sägs hysa flera spöken. Lady Carnarvon har själv berättat om en olycklig betjänt vars vålnad följt efter henne genom rummen. Slottet är öppet för besök delar av året.', 'published', 'wikipedia', '{"en":{"name":"Highclere Castle","teaser":"At the castle that plays Downton Abbey an unhappy footman is said to walk — the owner herself has described ghosts.","description":"Highclere Castle in Berkshire is famous as the filming location for Downton Abbey. The castle, home to the Carnarvon family — whose fifth Earl helped open Tutankhamun’s tomb in 1922 — is said to hold several ghosts. Lady Carnarvon has herself described an unhappy footman whose apparition followed her through the rooms. The castle is open to visitors part of the year."}}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
  name=EXCLUDED.name, teaser=EXCLUDED.teaser, description=EXCLUDED.description,
  country=EXCLUDED.country, region=EXCLUDED.region, type=EXCLUDED.type,
  lat=EXCLUDED.lat, lng=EXCLUDED.lng, scary=EXCLUDED.scary,
  translations=EXCLUDED.translations, status=EXCLUDED.status, source=EXCLUDED.source;
COMMIT;

-- hauntedplaces-intl-2026-07-14.sql  (världskända utländska spökplatser, batch 2)
-- 12 nya platser (10 USA + 2 UK) till Hauntedplaces + Spökkartan (projekt zffhdjogphqhcttkezsb).
-- Kurerade ur den notabla utländska delmängden; varje sägen webbverifierad (Wikipedia, hauntedrooms,
-- US Ghost Adventures m.fl.). Omtvistade legender skrivs som legender. Dedup mot 1305 live (namn+koordinat):
-- redan live t.ex. Queen Mary, Whaley House, Bird Cage, Alcatraz, Lemp, Villisca -> ej med.
-- Egen sv+en-text; källtext återges ALDRIG. Idempotent: ON CONFLICT (id) DO UPDATE.

BEGIN;
INSERT INTO places (id, name, slug, lat, lng, country, region, type, scary, free, bookable, teaser, description, status, source, translations) VALUES
('stanley-hotel-colorado', 'The Stanley Hotel', 'stanley-hotel-colorado', 40.383371, -105.5191728, 'USA', 'Colorado', 'Hotell', 4, false, true, 'Hotellet som inspirerade The Shining – i rum 217 sägs städerskan Elizabeth Wilson gå igen efter en explosion 1911.', 'The Stanley Hotel i Estes Park, Colorado, inspirerade Stephen King till The Shining efter en natt i rum 217. Just det rummet knyts till städerskan Elizabeth Wilson, som 1911 slungades genom golvet av en gasexplosion men överlevde – hennes vänliga vålnad sägs ännu ordna gästernas tillhörigheter. Från balsalen hörs pianotoner när ingen spelar, och barnröster i korridorerna på övervåningen.', 'published', 'wikipedia', '{"en":{"name":"The Stanley Hotel","teaser":"The hotel that inspired The Shining — in room 217 the housekeeper Elizabeth Wilson is said to linger after a 1911 explosion.","description":"The Stanley Hotel in Estes Park, Colorado, inspired Stephen King to write The Shining after a night in room 217. That room is tied to housekeeper Elizabeth Wilson, thrown through the floor by a 1911 gas explosion yet surviving — her friendly ghost is said to still tidy guests’ belongings. Piano notes drift from the ballroom when no one plays, and children’s voices are heard in the upstairs halls."}}'::jsonb),
('eastern-state-penitentiary-pennsylvania', 'Eastern State Penitentiary', 'eastern-state-penitentiary-pennsylvania', 39.9683364, -75.1726648, 'USA', 'Pennsylvania', 'Fängelse', 5, false, true, 'I det övergivna fängelset darrar skuggestalter längs cellblocken – en låssmed berättade om en kraft som grep tag i honom.', 'Eastern State Penitentiary i Philadelphia, en gång världens dyraste fängelse med sin isoleringsregim, räknas till USA:s mest hemsökta. Besökare berättar om kacklande skratt i cellblock 12, skuggestalter som glider längs väggarna i block 6 och ansikten i block 4. En underhållsarbetare, Gary Johnson, sade sig ha känt en kraft gripa tag i honom så hårt att han inte kunde röra sig. Ruinen är i dag museum.', 'published', 'wikipedia', '{"en":{"name":"Eastern State Penitentiary","teaser":"In the abandoned prison shadow figures flit along the cellblocks — a locksmith told of a force that seized him.","description":"Eastern State Penitentiary in Philadelphia, once the world’s most expensive prison with its regime of solitude, ranks among America’s most haunted. Visitors report cackling laughter in Cellblock 12, shadow figures sliding along the walls of Block 6, and faces in Block 4. A maintenance worker, Gary Johnson, said a force gripped him so hard he could not move. The ruin is a museum today."}}'::jsonb),
('waverly-hills-sanatorium-kentucky', 'Waverly Hills Sanatorium', 'waverly-hills-sanatorium-kentucky', 38.1302387, -85.8411866, 'USA', 'Kentucky', 'Sanatorium', 5, false, true, 'Genom "dödstunneln" firades tusentals lik ner i hemlighet – och i rum 502 sägs en röst skrika "Get out!".', 'Waverly Hills Sanatorium i Louisville, Kentucky, var ett tuberkulossjukhus där tusentals dog under "den vita pestens" år. De döda firades i hemlighet ner för berget genom den så kallade dödstunneln (the body chute). Där berättar besökare om släpande ljud, viskningar och gestalter i mörkret, och i det ökända rum 502 ska en osynlig röst ha skrikit åt folk att ge sig av. Byggnaden är ett av USA:s mest ökända spökhus.', 'published', 'wikipedia', '{"en":{"name":"Waverly Hills Sanatorium","teaser":"Through the \"death tunnel\" thousands of bodies were lowered in secret — and in Room 502 a voice is said to scream \"Get out!\".","description":"Waverly Hills Sanatorium in Louisville, Kentucky, was a tuberculosis hospital where thousands died during the years of the \"white plague\". The dead were lowered down the hillside in secret through the so-called death tunnel, or body chute. There visitors describe dragging sounds, whispers and figures in the dark, and in the infamous Room 502 an unseen voice is said to have screamed at people to leave. The building is one of America’s most notorious haunted sites."}}'::jsonb),
('myrtles-plantation-louisiana', 'Myrtles Plantation', 'myrtles-plantation-louisiana', 30.8034022, -91.3880495, 'USA', 'Louisiana', 'Herrgård', 4, false, true, 'Sägnen berättar om slavinnan Chloe, som förlorade ett öra och sägs vandra i sin gröna turban – men historiker betvivlar historien.', 'Myrtles Plantation i St. Francisville, Louisiana, från 1796, kallas ofta ett av USA:s mest hemsökta hem. Den mest kända sägnen handlar om slavinnan Chloe, som enligt berättelsen fick ett öra avskuret och bar en grön turban för att dölja det, och som ska ha förgiftat familjens barn med oleander. Historiker påpekar att det saknas belägg för Chloe och att dödsfallen berodde på gula febern – men på plantagen berättas ännu om speglar, spöklika barn och gestalter på verandan.', 'published', 'wikipedia', '{"en":{"name":"Myrtles Plantation","teaser":"Legend tells of the enslaved woman Chloe, who lost an ear and is said to walk in her green turban — though historians doubt the tale.","description":"Myrtles Plantation in St. Francisville, Louisiana, built in 1796, is often called one of America’s most haunted homes. Its best-known legend concerns Chloe, an enslaved woman said to have had an ear cut off and to have worn a green turban to hide it, and to have poisoned the family’s children with oleander. Historians note there is no record of Chloe and that the deaths were from yellow fever — yet the plantation still tells of mirrors, ghostly children and figures on the veranda."}}'::jsonb),
('winchester-mystery-house-california', 'Winchester Mystery House', 'winchester-mystery-house-california', 37.3183318, -121.9510491, 'USA', 'California', 'Herrgård', 4, false, true, 'Änkan Sarah Winchester lät bygga i 36 år på ett hus med trappor som slutar i tak – enligt sägnen för att förvirra andarna efter gevärens offer.', 'Winchester Mystery House i San Jose, Kalifornien, byggdes om oavbrutet i 36 år av änkan Sarah Winchester. Enligt den populära sägnen höll hon séanser och lät bygga labyrintiska korridorer, trappor som slutar i tak och dörrar som öppnas mot tomma intet för att förvirra andarna efter alla som dödats av familjens Winchestergevär. Historiker menar att de udda dragen mest beror på jordbävningsskador och ständiga ombyggnader – men huset förblir en av USA:s mest berömda spökbyggnader.', 'published', 'wikipedia', '{"en":{"name":"Winchester Mystery House","teaser":"The widow Sarah Winchester built for 36 years a house with stairs that end at the ceiling — by legend, to confuse the ghosts of the rifle’s victims.","description":"Winchester Mystery House in San Jose, California, was rebuilt without pause for 36 years by the widow Sarah Winchester. By popular legend she held séances and built labyrinthine corridors, stairs that end at the ceiling and doors that open onto nothing, to confuse the spirits of all killed by the family’s Winchester rifles. Historians hold the oddities owe more to earthquake damage and constant remodelling — yet the house remains one of America’s most famous haunted buildings."}}'::jsonb),
('franklin-castle-ohio', 'Franklin Castle', 'franklin-castle-ohio', 41.4857366, -81.7165798, 'USA', 'Ohio', 'Hus', 3, false, true, 'Ohios mest hemsökta hus – där bankiren Tiedemann såg flera i sin familj dö, och gråt sägs höras ur väggarna.', 'Franklin Castle (Tiedemann-huset) i Cleveland, Ohio, byggt på 1880-talet av bankiren Hannes Tiedemann, kallas ofta delstatens mest hemsökta hem. Tiedemann drabbades av en rad tragedier då flera i familjen dog, och sedan 1960-talet berättas om barngråt ur väggarna, steg i tomma rum och en kvinna i svart. Den mörka stenbyggnaden i Queen Anne-stil är en klassiker i amerikansk spökfolklore.', 'published', 'wikipedia', '{"en":{"name":"Franklin Castle","teaser":"Ohio’s most haunted house — where the banker Tiedemann saw several of his family die, and crying is said to seep from the walls.","description":"Franklin Castle (the Tiedemann House) in Cleveland, Ohio, built in the 1880s by banker Hannes Tiedemann, is often called the state’s most haunted home. Tiedemann suffered a string of tragedies as several family members died, and since the 1960s there have been accounts of a child’s crying from the walls, footsteps in empty rooms and a woman in black. The dark Queen Anne stone house is a classic of American ghost lore."}}'::jsonb),
('uss-hornet-california', 'USS Hornet', 'uss-hornet-california', 37.7726482, -122.3025322, 'USA', 'California', 'Museum', 3, false, true, 'På det hemsökta hangarfartyget dog över 300 man – och en sjöman i vit paraduniform sägs ännu synas ombord.', 'USS Hornet, ett hangarfartyg från andra världskriget som nu är museum i Alameda, Kalifornien, räknas till USA:s mest hemsökta fartyg. Över 300 man förlorade livet ombord, och besökare berättar om "the Dress Whites Ghost" – en sjöman i vit paraduniform – samt om steg, röster och dörrar som rör sig av sig själva. Fartyget håller regelbundna spökvakor för besökare.', 'published', 'wikipedia', '{"en":{"name":"USS Hornet","teaser":"On the haunted aircraft carrier over 300 men died — and a sailor in white dress uniform is said to still appear aboard.","description":"USS Hornet, a World War II aircraft carrier now a museum in Alameda, California, is counted among America’s most haunted ships. Over 300 men lost their lives aboard, and visitors tell of the \"Dress Whites Ghost\" — a sailor in white dress uniform — as well as footsteps, voices and doors that move by themselves. The ship hosts regular overnight ghost watches."}}'::jsonb),
('molly-brown-house-colorado', 'Molly Brown House', 'molly-brown-house-colorado', 39.737494, -104.980736, 'USA', 'Colorado', 'Museum', 2, false, true, 'Titanic-överlevaren Molly Browns hem – där doften av J.J. Browns pipa dröjer och möbler flyttar sig.', 'Molly Brown House i Denver, Colorado, var hem för Margaret "Molly" Brown, som överlevde Titanics förlisning. I dag är det museum, och besökare och personal berättar om doften av piprök – tillskriven maken J.J. Brown – om möbler som flyttat sig och en kvinna i viktoriansk klädsel som skymtat medan hon ordnat i rummen. Ett stillsamt men välbelagt spökhus.', 'published', 'wikipedia', '{"en":{"name":"Molly Brown House","teaser":"Titanic survivor Molly Brown’s home — where the scent of J.J. Brown’s pipe lingers and furniture rearranges itself.","description":"The Molly Brown House in Denver, Colorado, was home to Margaret \"Molly\" Brown, who survived the sinking of the Titanic. Now a museum, visitors and staff tell of the scent of pipe smoke — attributed to her husband J.J. Brown — of furniture that has moved, and a woman in Victorian dress glimpsed tidying the rooms. A gentle but well-attested haunting."}}'::jsonb),
('point-lookout-lighthouse-maryland', 'Point Lookout Lighthouse', 'point-lookout-lighthouse-maryland', 38.0387818, -76.3220739, 'USA', 'Maryland', 'Fyr', 4, false, true, 'Fyren står på platsen för inbördeskrigets största fångläger – en fyrvaktarhustru och en sydstatssoldat sägs gå igen.', 'Point Lookout Lighthouse i Maryland reser sig på platsen för inbördeskrigets största fångläger, där tusentals dog. Fyren kallas ofta USA:s mest hemsökta. Den första fyrvaktarens hustru, Ann Davis, som dog i lanterninrummet, sägs synas överst i trappan i blå kjol och vit blus, och parkvakter berättar om en sydstatssoldat som skymtar i backspeglar. En paranormal utredare räknade 1980 till 24 andar i huset.', 'published', 'wikipedia', '{"en":{"name":"Point Lookout Lighthouse","teaser":"The lighthouse stands on the Civil War’s largest prison camp — a keeper’s wife and a Confederate soldier are said to walk.","description":"Point Lookout Lighthouse in Maryland rises on the site of the Civil War’s largest prison camp, where thousands died. It is often called America’s most haunted lighthouse. Ann Davis, the first keeper’s wife, who died in the lantern room, is said to appear at the top of the stairs in a blue skirt and white blouse, and rangers tell of a Confederate soldier glimpsed in rear-view mirrors. A paranormal investigator counted 24 spirits in the house in 1980."}}'::jsonb),
('fort-delaware-delaware', 'Fort Delaware', 'fort-delaware-delaware', 39.578484, -75.587367, 'USA', 'Delaware', 'Fästning', 3, false, true, 'På ökuborgen där inbördeskrigets fångar hölls dog omkring 2 500 man – kalla fläckar och gestalter sägs dröja kvar.', 'Fort Delaware på Pea Patch Island tjänade under inbördeskriget som fångläger för sydstatssoldater. Nära 13 000 hölls samtidigt och omkring 2 500 dog under svåra förhållanden. Besökare berättar om kalla fläckar, gestalter och obegripliga ljud i de gamla valven. Fästningen nås med färja och är i dag ett populärt mål för spökvakor.', 'published', 'wikipedia', '{"en":{"name":"Fort Delaware","teaser":"At the island fort that held Civil War prisoners some 2,500 men died — cold spots and figures are said to linger.","description":"Fort Delaware on Pea Patch Island served during the Civil War as a prison camp for Confederate soldiers. Nearly 13,000 were held at once and around 2,500 died in harsh conditions. Visitors tell of cold spots, figures and unexplained sounds in the old vaults. Reached by ferry, the fort is today a popular destination for ghost watches."}}'::jsonb),
('ancient-ram-inn-gloucestershire', 'Ancient Ram Inn', 'ancient-ram-inn-gloucestershire', 51.6378241, -2.3547251, 'UK', 'Gloucestershire', 'Värdshus', 5, false, true, 'Ett av Storbritanniens mest hemsökta hus – i "Häxans rum" sägs en bränd häxa från 1500-talet dröja kvar.', 'Ancient Ram Inn i Wotton-under-Edge, Gloucestershire, brukar kallas Storbritanniens mest hemsökta byggnad. Enligt sägnen sökte en häxa skydd här på 1500-talet undan häxjägarna men greps och brändes – rummet där hon gömde sig kallas i dag Häxans rum, där hennes vålnad sägs finnas kvar. Besökare berättar om en osynlig kraft, röster och känslan av att bli vidrörd. Huset vilar på en mycket äldre kultplats.', 'published', 'wikipedia', '{"en":{"name":"Ancient Ram Inn","teaser":"One of Britain’s most haunted houses — in the \"Witch’s Room\" a witch burned in the 1500s is said to linger.","description":"The Ancient Ram Inn in Wotton-under-Edge, Gloucestershire, is often called Britain’s most haunted building. By legend a witch sought refuge here in the 1500s from the witch-hunters but was seized and burned — the room where she hid is today called the Witch’s Room, where her ghost is said to remain. Visitors tell of an unseen force, voices and the feeling of being touched. The house sits on a far older ritual site."}}'::jsonb),
('ordsall-hall-salford', 'Ordsall Hall', 'ordsall-hall-salford', 53.469393, -2.277508, 'UK', 'Salford', 'Herrgård', 3, false, true, 'Den vita damen sägs vara Margaret Radclyffe, som dog av krossat hjärta 1599 och vandrar med ett ljus.', 'Ordsall Hall i Salford är en tudorherrgård vars mest kända spöke är den vita damen. Hon sägs vara Margaret Radclyffe, som bodde här i slutet av 1500-talet och dog av sorg 1599 efter att ha förlorat sin bror. Hon har rapporterats vandra genom salarna och Star Chamber med ett ljus i handen. Herrgården är i dag museum med egna spökberättelser.', 'published', 'wikipedia', '{"en":{"name":"Ordsall Hall","teaser":"The White Lady is said to be Margaret Radclyffe, who died of a broken heart in 1599 and walks carrying a candle.","description":"Ordsall Hall in Salford is a Tudor manor whose best-known ghost is the White Lady. She is said to be Margaret Radclyffe, who lived here in the late 1500s and died of grief in 1599 after losing her brother. She has been reported walking the halls and the Star Chamber holding a candle. The hall is a museum today, with ghost stories of its own."}}'::jsonb)
